declare const performance: { now(): number };

// Generated by the WASM build; allows checking source before the generated files exist.
declare module '*build/web/engine_core.js' {
  export default function init(): Promise<import('./native/BrowserEngine').WasmCore>;
  export function attach_canvas(id: number, canvas: HTMLCanvasElement): Promise<void>;
  export function install_asset_storage(driver: unknown): void;
  export function can_warm_asset_record(bytes: number): boolean;
  export function restore_asset_record(name: string, bytes: Uint8Array): boolean;
  export function read_saved_asset(key: string): Promise<Uint8Array>;
}
